head.script:
///////// 1. 변수 및 선언 영역 /////////
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.

            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값

        }

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        // buttonSet.setDsclInfo( btn_Dscl, fn_dscl );            // 안내문작성

        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.search();
        } else {
            await scwin.newOnload(); // 신규작성시 호출

        }
        $c.libRoundPanel.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05911.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_MktactEnforceDd_onclick
 * @description img_MktactEnforceDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MktactEnforceDd_onclick = function() {
    try {
        popUpCalendar2(edt_MktactEnforceDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05911.img_MktactEnforceDd_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
            //    dts_Isu.AddRow();

        } else {
            if (dts_Isu.getRowCount() > 0) {
                edt_MktactEnforceDd.setValue(dts_Isu.getCellData(1, "CHG_DD"));
                txb_ChgRsnContn.setValue(dts_Isu.getCellData(1, "CHG_RSN_CONTN"));
            }
            $c.stf.setButtonSetWithDate(edt_MktactEnforceDd, false);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05911.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_SetIsuCd_onclick
 * @description img_SetIsuCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = function() {
    try {
        fn_GetPar = scwin.getParIsu;
        fn_SetPar = scwin.setParIsu;
        $c.lc.fn_PopFindElwCode();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05911.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF05911.xml", SCREN_PROCS_TP_CD_07);
        if (dts_Isu.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd_isu, {fileName: "ELW 행사겨격/전환비율 변경", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_exelUpload_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_exelUpload_onclick = function() {
    try {
        const res = window.confirm("엑셀자료를 업로드 하시면 그리드의 내용이 엑셀 데이터로 변경됩니다.");
        if (res) {

            // dts_Isu.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            dts_Isu.Do("LoadExcelData", "'','Sheet1',2,0,2");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05911.btn_exelUpload_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF05911.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Isu",
            action : "/Listing.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "&SCREN_ID=" + "ULDSTF05911.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CHGLIST_PRC_INOUT";
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description save Trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    grd_isu.redraw = false;
    dts_Isu.setBroadcast(false);
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        dts_Isu.setCellData(i, "ISUR_CD", scwin.Isur_cd);
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Isu.setCellData(i, "CHG_DD", edt_MktactEnforceDd.getValue());
        dts_Isu.setCellData(i, "CHG_RSN_CONTN", txb_ChgRsnContn.getValue());
    }
    dts_Isu.setBroadcast(true, true);
    grd_isu.redraw = true;
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_147 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_PRC
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/Listing.do",
        ref : "dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsu
 * @description get Par Isu 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.getParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.gubun;
    $c.stf.copyDataSet(dts_Isu, param_dts);
};

/**
 * @method
 * @name setParIsu
 * @description set Par Isu 처리
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.setParIsu = function(param_dts) {
    $c.stf.copyDataSet(param_dts, dts_Isu);
    // alert(dts_Isu.text + "\n\n" + param_dts.text);

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (!$c.lc.checkDdTm("DD", edt_MktactEnforceDd, "변경상장", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_ChgRsnContn, "변경사유")) return false;
    if (!$c.stf.checkMaxLength(txb_ChgRsnContn, 2000, "변경사유")) return false;
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return false;
    }
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        if (dts_Isu.getCellData(i, "AFCHG_EXER_PRC") === "" || dts_Isu.getCellData(i, "AFCHG_EXER_PRC") === 0 ||
            dts_Isu.getCellData(i, "AFCHG_CONV_RTO") === "" || dts_Isu.getCellData(i, "AFCHG_CONV_RTO") === 0) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0019", ""));
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name drft
 * @description drft 처리
 * @returns {void}
 * @hidden N
 */
scwin.drft = function() {

};

/**
 * @method
 * @name makt
 * @description makt 처리
 * @returns {void}
 * @hidden N
 */
scwin.makt = function() {

};
